use vstd::prelude::*;

verus! {
    // Classify the safety of food based on days past since a reference day.
    //   x -- non-negative threshold (i8)
    //   a -- reference day (i8)
    //   b -- evaluation day  (i8)
    //
    // days_past = b - a (mathematical subtraction)
    //   ≤ 0        ⇒ "delicious"
    //   0 < days_past ≤ x ⇒ "safe"
    //   days_past > x     ⇒ "dangerous"
    fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str
        requires
            // threshold must be non-negative
            x >= 0
        ensures
            // Exactly one of the three cases holds, and matches the returned string
            (result == "delicious" 
                &&  b - a <=  0)
         ||
            (result == "safe"
                &&  b - a >   0
                &&  b - a <=  x)
         ||
            (result == "dangerous"
                &&  b - a >   x)
    {
        // Compute days past using a wider integer to avoid i8 under/overflow
        let days_past: i16 = b as i16 - a as i16;
        if days_past <= 0 {
            "delicious"
        } else if days_past <= x as i16 {
            "safe"
        } else {
            "dangerous"
        }
    }
}

fn main() {
    // Examples:
    assert!(determine_food_safety(5, 10,  8) == "delicious");
    assert!(determine_food_safety(5, 10, 10) == "delicious");
    assert!(determine_food_safety(5, 10, 12) == "safe");
    assert!(determine_food_safety(5, 10, 15) == "safe");
    assert!(determine_food_safety(5, 10, 16) == "dangerous");
}